<?php

declare(strict_types=1);
namespace StageArtCore\Presentation\Admin;
use StageArtCore\Presentation\PublicSite\SiteStructure;
use StageArtCore\Domain\Member\MemberRepository;

final class SiteStructureAdmin
{
    public function __construct(){add_action('admin_post_stageart_save_homepage',[$this,'saveHomepage']);add_action('admin_post_stageart_save_menu',[$this,'saveMenu']);}
    public function register():void{add_submenu_page('stageart-plugin','トップページ設定','トップページ設定','manage_options','stageart-homepage',[$this,'renderHomepage']);add_submenu_page('stageart-plugin','メニュー構成','メニュー構成','manage_options','stageart-menu',[$this,'renderMenu']);}
    private function data():array{return[get_posts(['post_type'=>'stageart_production','post_status'=>['publish','draft'],'numberposts'=>-1,'orderby'=>'title','order'=>'ASC']),(new MemberRepository())->all(false)];}
    private function picker(array$p,array$m,string$selected):string{$h='<option value="">選択してください</option><optgroup label="システムページ">';foreach(SiteStructure::systemLabels()as$k=>$v)$h.='<option value="system:'.esc_attr($k).'"'.selected($selected,'system:'.$k,false).'>'.esc_html($v).'</option>'; $h.='</optgroup><optgroup label="公演">';foreach($p as$x)$h.='<option value="production:'.(int)$x->ID.'"'.selected($selected,'production:'.$x->ID,false).'>'.esc_html($x->post_title).'</option>'; $h.='</optgroup><optgroup label="メンバー">';foreach($m as$x)$h.='<option value="member:'.(int)$x['id'].'"'.selected($selected,'member:'.$x['id'],false).'>'.esc_html($x['name']).'</option>';return$h.'</optgroup><optgroup label="外部リンク"><option value="url:"'.(str_starts_with($selected,'url:')?' selected':'').'>外部URL</option></optgroup>';}
    public function saveHomepage():void{if(!current_user_can('manage_options'))wp_die('権限がありません。');check_admin_referer('stageart_homepage');$out=[];foreach((array)wp_unslash($_POST['sections']??[])as$s){if(!is_array($s))continue;$slots=[];foreach((array)($s['slots']??[])as$slot){if(!is_array($slot))continue;$type=($slot['type']??'link')==='heading'?'heading':'link';$ref=$type==='heading'?sanitize_text_field((string)($slot['heading_text']??'')):sanitize_text_field((string)($slot['content']??''));if(!$ref)continue;if($type==='heading'){$slots[]=['type'=>'heading','ref'=>$ref];continue;}[$kind,$value]=array_pad(explode(':',$ref,2),2,'');if(!in_array($kind,['system','production','member','url'],true)||!$value)continue;$slots[]=['type'=>$kind,'ref'=>$kind==='url'?esc_url_raw($value):$value];}$out[]=['section_id'=>sanitize_key((string)($s['section_id']??wp_generate_uuid4())),'heading'=>sanitize_text_field((string)($s['heading']??'')),'columns'=>max(1,min(20,(int)($s['columns']??1))),'layout'=>($s['layout']??'horizontal')==='vertical'?'vertical':'horizontal','slots'=>$slots];}update_option(SiteStructure::HOME_OPTION,$out,false);wp_safe_redirect(admin_url('admin.php?page=stageart-homepage&saved=1'));exit;}
    public function saveMenu():void{if(!current_user_can('manage_options'))wp_die('権限がありません。');check_admin_referer('stageart_menu');$out=[];foreach((array)wp_unslash($_POST['menu']??[])as$i=>$item){if(!is_array($item))continue;$type=($item['type']??'content')==='folder'?'folder':'content';$content=(string)($item['content']??'');[$rt,$ref]=array_pad(explode(':',$content,2),2,'');if(!in_array($rt,['system','production','member','url'],true)){$rt='system';$ref='';}if($rt==='url')$ref=esc_url_raw($ref);else$ref=sanitize_text_field($ref);$out[]=['id'=>sanitize_key((string)($item['id']??wp_generate_uuid4())),'parent_id'=>sanitize_key((string)($item['parent_id']??'')),'type'=>$type,'ref_type'=>$rt,'ref_id'=>$ref,'label'=>sanitize_text_field((string)($item['label']??'')),'order'=>max(1,(int)($item['order']??$i+1))];}update_option(SiteStructure::MENU_OPTION,$out,false);wp_safe_redirect(admin_url('admin.php?page=stageart-menu&saved=1'));exit;}
    public function renderHomepage():void{$sections=SiteStructure::homepageSections();[$p,$m]=$this->data();echo'<div class="wrap"><h1>トップページ設定</h1>';if(isset($_GET['saved']))echo'<div class="notice notice-success"><p>保存しました。</p></div>';echo'<p>Alumniと同じセクション＋スロット方式です。メニュー構成とは完全に分離しています。</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('stageart_homepage');echo'<input type="hidden" name="action" value="stageart_save_homepage"><div id="sa-home-sections">';foreach($sections as$i=>$s)$this->homeSection($i,$s,$p,$m);echo'</div><p><button type="button" class="button" id="sa-add-home-section">＋ セクションを追加</button></p>';submit_button('トップページを保存');echo'</form>';$this->homeJs($p,$m);echo'</div>';}
    private function homeSection(int$i,array$s,array$p,array$m):void{echo'<fieldset class="card sa-home-section" style="margin:16px 0;padding:16px"><legend><strong>セクション</strong></legend><input type="hidden" name="sections['.$i.'][section_id]" value="'.esc_attr($s['section_id']).'"><p><label>見出し（任意）<br><input class="regular-text" name="sections['.$i.'][heading]" value="'.esc_attr($s['heading']).'"></label>　<label>表示数 <select name="sections['.$i.'][columns]">';for($n=1;$n<=20;$n++)echo'<option value="'.$n.'"'.selected((int)$s['columns'],$n,false).'>'.$n.'件</option>';echo'</select></label>　<label>表示方向 <select name="sections['.$i.'][layout]"><option value="horizontal"'.selected($s['layout'],'horizontal',false).'>横並び</option><option value="vertical"'.selected($s['layout'],'vertical',false).'>縦並び</option></select></label> <button type="button" class="button-link-delete" data-remove-section>削除</button></p><div class="sa-home-slots">';foreach((array)$s['slots']as$j=>$slot){$heading=$slot['type']==='heading';$sel=$heading?'':$slot['type'].':'.$slot['ref'];echo'<div class="sa-home-slot" style="display:flex;gap:8px;margin:6px 0"><select name="sections['.$i.'][slots]['.$j.'][type]" data-slot-type><option value="link"'.selected(!$heading,true,false).'>コンテンツリンク</option><option value="heading"'.selected($heading,true,false).'>見出し</option></select><select class="regular-text" name="sections['.$i.'][slots]['.$j.'][content]" data-slot-content>'. $this->picker($p,$m,$sel).'</select><input class="regular-text" name="sections['.$i.'][slots]['.$j.'][heading_text]" value="'.($heading?esc_attr($slot['ref']):'').'" placeholder="見出し" data-slot-heading style="display:'.($heading?'inline-block':'none').'"> <button type="button" class="button-link-delete" data-remove-slot>削除</button></div>';}echo'</div><p><button type="button" class="button" data-add-slot>＋ コンテンツを追加</button></p></fieldset>';}
    private function homeJs(array$p,array$m):void{$opts=$this->picker($p,$m,'');echo'<script>(function(){const root=document.getElementById("sa-home-sections"),add=document.getElementById("sa-add-home-section"),opts='.wp_json_encode($opts).';if(!root||!add)return;function wire(row){const t=row.querySelector("[data-slot-type]"),c=row.querySelector("[data-slot-content]"),h=row.querySelector("[data-slot-heading]");t.onchange=function(){const x=t.value==="heading";c.style.display=x?"none":"inline-block";h.style.display=x?"inline-block":"none"};t.onchange()}root.querySelectorAll(".sa-home-slot").forEach(wire);root.onclick=function(e){if(e.target.matches("[data-remove-section]")){e.target.closest(".sa-home-section").remove();return}if(e.target.matches("[data-remove-slot]")){e.target.closest(".sa-home-slot").remove();return}if(e.target.matches("[data-add-slot]")){const s=e.target.closest(".sa-home-section"),wrap=s.querySelector(".sa-home-slots"),i=wrap.children.length,row=document.createElement("div");row.className="sa-home-slot";row.style="display:flex;gap:8px;margin:6px 0";row.innerHTML="<select name=\"sections[0][slots]["+i+"][type]\" data-slot-type><option value=\"link\">コンテンツリンク</option><option value=\"heading\">見出し</option></select><select class=\"regular-text\" name=\"sections[0][slots]["+i+"][content]\" data-slot-content>"+opts+"</select><input class=\"regular-text\" name=\"sections[0][slots]["+i+"][heading_text]\" data-slot-heading placeholder=\"見出し\" style=\"display:none\"><button type=\"button\" class=\"button-link-delete\" data-remove-slot>削除</button>";wrap.appendChild(row);wire(row)}};add.onclick=function(){const i=root.children.length,fs=document.createElement("fieldset");fs.className="card sa-home-section";fs.style="margin:16px 0;padding:16px";fs.innerHTML="<legend><strong>セクション</strong></legend><input type=\"hidden\" name=\"sections["+i+"][section_id]\" value=\"new-"+Date.now()+"\"><p><label>見出し（任意）<br><input class=\"regular-text\" name=\"sections["+i+"][heading]\"></label>　<label>表示数 <select name=\"sections["+i+"][columns]\"><option>1</option><option>2</option><option>3</option></select></label>　<label>表示方向 <select name=\"sections["+i+"][layout]\"><option value=\"horizontal\">横並び</option><option value=\"vertical\">縦並び</option></select></label> <button type=\"button\" class=\"button-link-delete\" data-remove-section>削除</button></p><div class=\"sa-home-slots\"></div><p><button type=\"button\" class=\"button\" data-add-slot>＋ コンテンツを追加</button></p>";root.appendChild(fs)}})();</script>';}
    public function renderMenu():void{$menu=SiteStructure::menuItems();[$p,$m]=$this->data();echo'<div class="wrap"><h1>メニュー構成</h1>';if(isset($_GET['saved']))echo'<div class="notice notice-success"><p>保存しました。</p></div>';echo'<p>トップページのページ配置とは独立したサイトメニューです。項目種別はコンテンツリンク／フォルダです。</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('stageart_menu');echo'<input type="hidden" name="action" value="stageart_save_menu"><div id="sa-menu-items">';foreach($menu as$i=>$item)$this->menuRow($i,$item,$menu,$p,$m);echo'</div><p><button type="button" class="button" id="sa-add-menu">＋ メニュー項目を追加</button></p>';submit_button('メニューを保存');echo'</form><script>'. $this->menuJs($p,$m).'</script></div>';}
    private function menuRow(int$i,array$item,array$all,array$p,array$m):void{$sel=$item['ref_type'].':'.$item['ref_id'];echo'<div class="card sa-menu-row" style="margin:10px 0;padding:12px"><input type="hidden" name="menu['.$i.'][id]" value="'.esc_attr($item['id']).'"><p><label>表示名 <input name="menu['.$i.'][label]" value="'.esc_attr($item['label']).'" required></label>　<label>順序 <input type="number" min="1" name="menu['.$i.'][order]" value="'.esc_attr($item['order']).'" style="width:70px"></label>　<label>項目種別 <select name="menu['.$i.'][type]"><option value="content"'.selected($item['type'],'content',false).'>コンテンツリンク</option><option value="folder"'.selected($item['type'],'folder',false).'>フォルダ</option></select></label>　<label>親 <select name="menu['.$i.'][parent_id]"><option value="">（なし）</option>';foreach($all as$x){if($x['id']===$item['id'])continue;echo'<option value="'.esc_attr($x['id']).'"'.selected($item['parent_id'],$x['id'],false).'>'.esc_html($x['label']?:'（無題）').'</option>';}echo'</select></label></p><p><label>コンテンツリンク <select name="menu['.$i.'][content]">'.$this->picker($p,$m,$sel).'</select></label> <button type="button" class="button-link-delete" data-remove-menu>削除</button></p></div>';}
    private function menuJs(array$p,array$m):string{$opts=$this->picker($p,$m,'');return'<script>(function(){const root=document.getElementById("sa-menu-items"),add=document.getElementById("sa-add-menu"),opts='.wp_json_encode($opts).';if(!root||!add)return;add.onclick=function(){const i=root.children.length,row=document.createElement("div");row.className="card sa-menu-row";row.style="margin:10px 0;padding:12px";row.innerHTML="<input type=\"hidden\" name=\"menu["+i+"][id]\" value=\"new-"+Date.now()+"\"><p><label>表示名 <input name=\"menu["+i+"][label]\" required></label>　<label>順序 <input type=\"number\" min=\"1\" name=\"menu["+i+"][order]\" value=\""+(i+1)+"\"></label>　<label>項目種別 <select name=\"menu["+i+"][type]\"><option value=\"content\">コンテンツリンク</option><option value=\"folder\">フォルダ</option></select></label>　<label>親 <select name=\"menu["+i+"][parent_id]\"><option value=\"\">（なし）</option></select></label></p><p><label>コンテンツリンク <select name=\"menu["+i+"][content]\">"+opts+"</select></label> <button type=\"button\" class=\"button-link-delete\" data-remove-menu>削除</button></p>";root.appendChild(row)};root.onclick=function(e){if(e.target.matches("[data-remove-menu]"))e.target.closest(".sa-menu-row").remove()}})();</script>'}
}
